-- ba trang pháp lý tiếng Việt đã soạn từ trước.
UPDATE `qlo_cms_lang` SET `meta_title` = 'Policies', `meta_description` = 'Our policies of hotel bookings', `content` = '<h2 class=\"page-heading bottom-indent\">Policies</h2>\n      <div>\n      <p style=\"border-left:2px solid #808080;padding-left:5px;\">This page contains demo content for illustrative purposes only. Any resemblance to actual products, services, or events is purely coincidental. Thank you for your understanding.</p>\n      <hr /></div>\n      <div>\n      <p class=\"page-subheading\">Reservation Policy:</p>\n      <ul class=\"margin-btm-30\">\n      <li class=\"margin-btm-10\">Guests must provide valid credit card details to secure a reservation.</li>\n      <li class=\"margin-btm-10\">Cancellation policies vary based on room type and rate plan.</li>\n      <li class=\"margin-btm-10\">Changes to reservations may be subject to availability and additional charges.</li>\n      </ul>\n      <p class=\"page-subheading\">Check-in and Check-out Times:</p>\n      <ul class=\"margin-btm-30\">\n      <li class=\"margin-btm-10\">Check-in time: 11:00 AM</li>\n      <li class=\"margin-btm-10\">Check-out time: 10:30 AM</li>\n      <li class=\"margin-btm-10\">Early check-in and late check-out requests are subject to availability and may incur additional charges.</li>\n      </ul>\n      <p class=\"page-subheading\">Payment Policy:</p>\n      <ul class=\"margin-btm-30\">\n      <li class=\"margin-btm-10\">Payment for the entire stay is due upon check-in.</li>\n      <li class=\"margin-btm-10\">Acceptable forms of payment: credit cards, cash, etc.</li>\n      <li class=\"margin-btm-10\">A security deposit may be required upon arrival.</li>\n      </ul>\n      <p class=\"page-subheading\">Cancellation and No-show Policy:</p>\n      <ul class=\"margin-btm-30\">\n      <li class=\"margin-btm-10\">Cancellations made 7 days prior to arrival are eligible for a full refund.</li>\n      <li class=\"margin-btm-10\">No-shows will be charged the full amount of the reservation.</li>\n      </ul>\n      <p class=\"page-subheading\">Pet Policy:</p>\n      <ul class=\"margin-btm-30\">\n      <li class=\"margin-btm-10\">Pets are welcome with prior arrangement.</li>\n      <li class=\"margin-btm-10\">Additional charges may apply for pet-friendly accommodations.</li>\n      <li class=\"margin-btm-10\">Guests are responsible for any damages caused by their pets.</li>\n      </ul>\n      <p class=\"page-subheading\">Smoking Policy:</p>\n      <ul class=\"margin-btm-30\">\n      <li class=\"margin-btm-10\">Our hotel is smoke-free. Smoking is strictly prohibited indoors.</li>\n      <li class=\"margin-btm-10\">Designated smoking areas are available outside the premises.</li>\n      </ul>\n      <p class=\"page-subheading\">Privacy Policy:</p>\n      <ul class=\"margin-btm-30\">\n      <li class=\"margin-btm-10\">We are committed to protecting your privacy and personal information.</li>\n      <li class=\"margin-btm-10\">Information collected during booking and stay is used solely for operational purposes.</li>\n      </ul>\n      <p class=\"page-subheading\">Accessibility Policy:</p>\n      <ul class=\"margin-btm-30\">\n      <li class=\"margin-btm-10\">Our hotel is committed to providing accessible accommodations and facilities for guests with disabilities.</li>\n      <li class=\"margin-btm-10\">Please contact us directly for specific accessibility requests.</li>\n      </ul>\n      <p class=\"page-subheading\">Additional Policies:</p>\n      <ul class=\"margin-btm-30\">\n      <li class=\"margin-btm-10\">Use of hotel facilities such as the gym, spa, pool, etc.</li>\n      <li class=\"margin-btm-10\">Conduct and behavior expectations while on hotel premises.</li>\n      </ul>\n      </div>\n    ' WHERE `id_cms` = 1 AND `id_lang` = 1;
UPDATE `qlo_cms_lang` SET `meta_title` = 'Chính sách', `meta_description` = 'Chính sách của chúng tôi về đặt phòng khách sạn', `content` = '<h2 class=\"page-heading bottom-indent\">Chính sách</h2>\n      <div>\n      <p style=\"border-left:2px solid #808080;padding-left:5px;\">Trang này chứa nội dung minh họa cho mục đích giải thích. Mọi sự giống nhau với các sản phẩm, dịch vụ hoặc sự kiện thực tế là hoàn toàn ngẫu nhiên. Cảm ơn bạn đã hiểu.</p>\n      <hr /></div>\n      <div>\n      <p class=\"page-subheading\">Chính sách đặt phòng:</p>\n      <ul class=\"margin-btm-30\">\n      <li class=\"margin-btm-10\">Khách hàng phải cung cấp thông tin thẻ tín dụng hợp lệ để đảm bảo việc đặt chỗ.</li>\n      <li class=\"margin-btm-10\">Chính sách hủy đặt phòng thay đổi tùy theo loại phòng và kế hoạch giá cả.</li>\n      <li class=\"margin-btm-10\">Thay đổi đặt phòng có thể phụ thuộc vào sự có sẵn và có thể có phí bổ sung.</li>\n      </ul>\n      <p class=\"page-subheading\">Thời gian nhận phòng và trả phòng:</p>\n      <ul class=\"margin-btm-30\">\n      <li class=\"margin-btm-10\">Thời gian nhận phòng: 11:00 AM</li>\n      <li class=\"margin-btm-10\">Thời gian trả phòng: 10:30 AM</li>\n      <li class=\"margin-btm-10\">Yêu cầu nhận phòng sớm và trả phòng muộn có thể phụ thuộc vào sự có sẵn và có thể có phí bổ sung.</li>\n      </ul>\n      <p class=\"page-subheading\">Chính sách thanh toán:</p>\n      <ul class=\"margin-btm-30\">\n      <li class=\"margin-btm-10\">Thanh toán cho toàn bộ thời gian lưu trú được thu khi nhận phòng.</li>\n      <li class=\"margin-btm-10\">Hình thức thanh toán chấp nhận: thẻ tín dụng, tiền mặt, v.v...</li>\n      <li class=\"margin-btm-10\">Có thể yêu cầu đặt cọc khi nhận phòng.</li>\n      </ul>\n      <p class=\"page-subheading\">Chính sách hủy và không có mặt:</p>\n      <ul class=\"margin-btm-30\">\n      <li class=\"margin-btm-10\">Hủy đặt phòng trước 7 ngày trước khi đến sẽ được hoàn trả toàn bộ tiền.</li>\n      <li class=\"margin-btm-10\">Khách không có mặt sẽ bị tính toàn bộ số tiền đặt phòng.</li>\n      </ul>\n      <p class=\"page-subheading\">Chính sách về thú nuôi:</p>\n      <ul class=\"margin-btm-30\">\n      <li class=\"margin-btm-10\">Thú nuôi được chào đón với sự sắp xếp trước.</li>\n      <li class=\"margin-btm-10\">Có thể áp dụng phí bổ sung cho các phòng cho thú cưng.</li>\n      <li class=\"margin-btm-10\">Khách hàng chịu trách nhiệm về bất kỳ thiệt hại nào do thú cưng gây ra.</li>\n      </ul>\n      <p class=\"page-subheading\">Chính sách không hút thuốc:</p>\n      <ul class=\"margin-btm-30\">\n      <li class=\"margin-btm-10\">Khách sạn của chúng tôi là không hút thuốc. Cấm hút thuốc tuyệt đối trong nhà.</li>\n      <li class=\"margin-btm-10\">Có các khu vực hút thuốc được chỉ định bên ngoài khuôn viên.</li>\n      </ul>\n      <p class=\"page-subheading\">Chính sách bảo mật:</p>\n      <ul class=\"margin-btm-30\">\n      <li class=\"margin-btm-10\">Chúng tôi cam kết bảo vệ quyền riêng tư và thông tin cá nhân của bạn.</li>\n      <li class=\"margin-btm-10\">Thông tin được thu thập trong quá trình đặt phòng và lưu trú chỉ được sử dụng cho mục đích vận hành.</li>\n      </ul>\n      <p class=\"page-subheading\">Chính sách về tiếp cận dễ dàng:</p>\n      <ul class=\"margin-btm-30\">\n      <li class=\"margin-btm-10\">Khách sạn của chúng tôi cam kết cung cấp các phòng nghỉ và cơ sở vật chất dễ dàng tiếp cận cho khách có khuyết tật.</li>\n      <li class=\"margin-btm-10\">Vui lòng liên hệ trực tiếp với chúng tôi để yêu cầu cụ thể về tiếp cận dễ dàng.</li>\n      </ul>\n      <p class=\"page-subheading\">Các chính sách bổ sung:</p>\n      <ul class=\"margin-btm-30\">\n      <li class=\"margin-btm-10\">Sử dụng các tiện nghi của khách sạn như phòng tập gym, spa, hồ bơi, v.v...</li>\n      <li class=\"margin-btm-10\">Kỳ vọng hành vi và hành vi khi ở trong khuôn viên khách sạn.</li>\n      </ul>\n      </div>\n    ' WHERE `id_cms` = 1 AND `id_lang` = 2;
UPDATE `qlo_cms_lang` SET `meta_title` = 'Legal Notice', `meta_description` = 'Legal notice', `content` = '\n      <h2 class=\"page-heading bottom-indent\"><strong>Legal Notice</strong></h2>\n      <div>\n      <p style=\"border-left:2px solid #808080;padding-left:5px;\">This page contains demo content for illustrative purposes only. Any resemblance to actual products, services, or events is purely coincidental. Thank you for your understanding.</p>\n      <hr /></div>\n      <p class=\"margin-btm-30 page-subheading\">Website Terms of Use:</p>\n      <ul class=\"margin-btm-30\">\n      <li class=\"margin-btm-20\">The content of the pages of this website is for your general information and use only. It is subject to change without notice.</li>\n      <li class=\"margin-btm-20\">Neither we nor any third parties provide any warranty or guarantee as to the accuracy, timeliness, performance, completeness, or suitability of the information and materials found or offered on this website for any particular purpose. You acknowledge that such information and materials may contain inaccuracies or errors, and we expressly exclude liability for any such inaccuracies or errors to the fullest extent permitted by law.</li>\n      <li class=\"margin-btm-20\">Your use of any information or materials on this website is entirely at your own risk, for which we shall not be liable. It shall be your own responsibility to ensure that any products, services, or information available through this website meet your specific requirements.</li>\n      </ul>\n      <p class=\"page-subheading\">Intellectual Property:</p>\n      <ul class=\"margin-btm-30\">\n      <li class=\"margin-btm-20\">This website contains material which is owned by or licensed to us. This material includes, but is not limited to, the design, layout, look, appearance, and graphics. Reproduction is prohibited other than in accordance with the copyright notice, which forms part of these terms and conditions.</li>\n      <li class=\"margin-btm-20\">All trademarks reproduced in this website, which are not the property of, or licensed to the operator, are acknowledged on the website.</li>\n      </ul>\n      <p class=\"page-subheading\">Privacy Policy:</p>\n      <ul class=\"margin-btm-30\">\n      <li class=\"margin-btm-20\">Your privacy is important to us. Please review our Privacy Policy to understand how we collect, use, and disclose information about you.</li>\n      </ul>\n      <p class=\"page-subheading\">Limitation of Liability:</p>\n      <ul class=\"margin-btm-30\">\n      <li class=\"margin-btm-20\">Neither we nor any third parties provide any warranty or guarantee as to the accuracy, timeliness, performance, completeness, or suitability of the information and materials found or offered on this website for any particular purpose. You acknowledge that such information and materials may contain inaccuracies or errors, and we expressly exclude liability for any such inaccuracies or errors to the fullest extent permitted by law.</li>\n      <li class=\"margin-btm-20\">Your use of any information or materials on this website is entirely at your own risk, for which we shall not be liable. It shall be your own responsibility to ensure that any products, services, or information available through this website meet your specific requirements.</li>\n      </ul>\n    ' WHERE `id_cms` = 2 AND `id_lang` = 1;
UPDATE `qlo_cms_lang` SET `meta_title` = 'Thông báo pháp lý', `meta_description` = 'Thông báo pháp lý của chúng tôi', `content` = '\n        <h2 class=\"page-heading bottom-indent\"><strong>Thông báo pháp lý</strong></h2>\n        <div>\n        <p style=\"border-left:2px solid #808080;padding-left:5px;\">Trang này chứa nội dung minh họa cho mục đích giảng dạy. Mọi sự tương đồng với sản phẩm, dịch vụ hoặc sự kiện thực tế là hoàn toàn ngẫu nhiên. Cảm ơn sự hiểu biết của bạn.</p>\n        <hr /></div>\n        <p class=\"margin-btm-30 page-subheading\">Điều khoản sử dụng Website:</p>\n        <ul class=\"margin-btm-30\">\n        <li class=\"margin-btm-20\">Nội dung của các trang web này chỉ dành cho mục đích thông tin và sử dụng chung của bạn. Nó có thể thay đổi mà không cần thông báo trước.</li>\n        <li class=\"margin-btm-20\">Chúng tôi cũng như bên thứ ba không đảm bảo hoặc cam kết bất kỳ bảo hành nào về độ chính xác, tính kịp thời, hiệu suất, đầy đủ hoặc phù hợp của thông tin và tài liệu được tìm thấy hoặc cung cấp trên trang web này cho bất kỳ mục đích cụ thể nào. Bạn công nhận rằng thông tin và tài liệu này có thể chứa sai sót hoặc lỗi, và chúng tôi tuyên bố loại trừ trách nhiệm về bất kỳ sai sót hoặc lỗi này theo pháp luật cho phép.</li>\n        <li class=\"margin-btm-20\">Việc sử dụng bất kỳ thông tin hoặc tài liệu nào trên trang web này hoàn toàn thuộc trách nhiệm của bạn, mà chúng tôi sẽ không chịu trách nhiệm. Điều này sẽ là trách nhiệm của bạn để đảm bảo rằng bất kỳ sản phẩm, dịch vụ hoặc thông tin nào có sẵn thông qua trang web này đáp ứng đầy đủ yêu cầu cụ thể của bạn.</li>\n        </ul>\n        <p class=\"page-subheading\">Sở hữu trí tuệ:</p>\n        <ul class=\"margin-btm-30\">\n        <li class=\"margin-btm-20\">Trang web này chứa tài liệu do chúng tôi sở hữu hoặc được cấp phép. Tài liệu này bao gồm nhưng không giới hạn đến thiết kế, bố cục, giao diện, và đồ họa. Sao chép là không được phép ngoại trừ theo thông báo bản quyền, là một phần của các điều khoản và điều kiện này.</li>\n        <li class=\"margin-btm-20\">Tất cả các nhãn hiệu được sao chép trong trang web này, không phải là tài sản của hoặc được cấp phép cho nhà khai thác, đều được công nhận trên trang web.</li>\n        </ul>\n        <p class=\"page-subheading\">Chính sách bảo mật:</p>\n        <ul class=\"margin-btm-30\">\n        <li class=\"margin-btm-20\">Quyền riêng tư của bạn là rất quan trọng với chúng tôi. Vui lòng xem lại Chính sách Bảo mật của chúng tôi để hiểu cách chúng tôi thu thập, sử dụng và tiết lộ thông tin về bạn.</li>\n        </ul>\n        <p class=\"page-subheading\">Giới hạn trách nhiệm:</p>\n        <ul class=\"margin-btm-30\">\n        <li class=\"margin-btm-20\">Chúng tôi cũng như bên thứ ba không đảm bảo hoặc cam kết bất kỳ bảo hành nào về độ chính xác, tính kịp thời, hiệu suất, đầy đủ hoặc phù hợp của thông tin và tài liệu được tìm thấy hoặc cung cấp trên trang web này cho bất kỳ mục đích cụ thể nào. Bạn công nhận rằng thông tin và tài liệu này có thể chứa sai sót hoặc lỗi, và chúng tôi tuyên bố loại trừ trách nhiệm về bất kỳ sai sót hoặc lỗi này theo pháp luật cho phép.</li>\n        <li class=\"margin-btm-20\">Việc sử dụng bất kỳ thông tin hoặc tài liệu nào trên trang web này hoàn toàn thuộc trách nhiệm của bạn, mà chúng tôi sẽ không chịu trách nhiệm. Điều này sẽ là trách nhiệm của bạn để đảm bảo rằng bất kỳ sản phẩm, dịch vụ, hoặc thông tin có sẵn qua trang web này đáp ứng đầy đủ yêu cầu cụ thể của bạn.</li>\n        </ul>\n    ' WHERE `id_cms` = 2 AND `id_lang` = 2;
UPDATE `qlo_cms_lang` SET `meta_title` = 'Terms and Conditions', `meta_description` = 'Our Terms and Conditions', `content` = '\n      <h2 class=\"page-heading bottom-indent\">Terms and Conditions</h2>\n      <div>\n      <p style=\"border-left:2px solid #808080;padding-left:5px;\">This page contains demo content for illustrative purposes only. Any resemblance to actual products, services, or events is purely coincidental. Thank you for your understanding.</p>\n      <hr /></div>\n      <div>\n      <h3 class=\"page-subheading\"><strong>Cancellation Policy:</strong></h3>\n      <div>\n      <ul>\n      <li><span>Free Cancellation: Up to 48 hours before arrival for standard rates.</span></li>\n      <li><span>Bookings made with a non-refundable rate cannot be canceled or modified.</span></li>\n      <li><span>Cancellations within 24 hours of arrival will incur a fee of one night\'s stay.</span></li>\n      </ul>\n      </div>\n      <br />\n      <h3 class=\"page-subheading\"><strong>Changes to Bookings:</strong></h3>\n      <div>\n      <ul>\n      <li><span>A fee of $25 may apply to change your reservation dates after booking.</span></li>\n      <li><span>Changes to room type or number of guests are subject to availability at the hotel.</span></li>\n      </ul>\n      </div>\n      <br />\n      <h3 class=\"page-subheading\"><strong>Guest Responsibility:</strong></h3>\n      <div>\n      <ul>\n      <li><span>All guests must present a valid government-issued photo ID at check-in.</span></li>\n      <li><span>The maximum occupancy for the room type is 2 adults.</span></li>\n      <li><span>Smoking and alcohol are strictly prohibited in all guest rooms and public areas.</span></li>\n      </ul>\n      </div>\n      </div>\n    ' WHERE `id_cms` = 3 AND `id_lang` = 1;
UPDATE `qlo_cms_lang` SET `meta_title` = 'Điều khoản và Điều kiện', `meta_description` = 'Điều khoản và điều kiện của chúng tôi', `content` = '\n        <h2 class=\"page-heading bottom-indent\">Điều khoản và Điều kiện</h2>\n        <div>\n        <p style=\"border-left:2px solid #808080;padding-left:5px;\">Trang này chứa nội dung minh họa cho mục đích giảng dạy. Mọi sự tương đồng với sản phẩm, dịch vụ hoặc sự kiện thực tế là hoàn toàn ngẫu nhiên. Cảm ơn sự hiểu biết của bạn.</p>\n        <hr /></div>\n        <div>\n        <h3 class=\"page-subheading\"><strong>Chính sách Hủy đặt phòng:</strong></h3>\n        <div>\n        <ul>\n        <li><span>Miễn phí Hủy đặt phòng: Được thực hiện trong vòng 48 giờ trước khi đến với giá chuẩn.</span></li>\n        <li><span>Các đặt phòng với giá không hoàn lại không thể bị hủy hoặc sửa đổi.</span></li>\n        <li><span>Việc hủy đặt phòng trong vòng 24 giờ trước khi đến sẽ phải chịu phí một đêm.</span></li>\n        </ul>\n        </div>\n        <br />\n        <h3 class=\"page-subheading\"><strong>Thay đổi Đặt phòng:</strong></h3>\n        <div>\n        <ul>\n        <li><span>Có thể áp dụng phí $25 cho việc thay đổi ngày đặt phòng sau khi đặt.</span></li>\n        <li><span>Thay đổi loại phòng hoặc số lượng khách là tùy thuộc vào sự có sẵn tại khách sạn.</span></li>\n        </ul>\n        </div>\n        <br />\n        <h3 class=\"page-subheading\"><strong>Trách nhiệm của Khách:</strong></h3>\n        <div>\n        <ul>\n        <li><span>Tất cả khách hàng phải xuất trình giấy tờ tùy thân có hình ảnh do chính phủ cấp tại quầy nhận phòng.</span></li>\n        <li><span>Sức chứa tối đa cho loại phòng là 2 người lớn.</span></li>\n        <li><span>Hút thuốc và uống rượu là nghiêm cấm tại tất cả các phòng và khu vực công cộng.</span></li>\n        </ul>\n        </div>\n        </div>\n    ' WHERE `id_cms` = 3 AND `id_lang` = 2;
UPDATE `qlo_cms_lang` SET `meta_title` = 'Giới thiệu', `meta_description` = 'Thaithinh Hotel - hệ thống 3 cơ sở tại Hồ Chí Minh, Đà Nẵng, Hà Nội với 50 phòng. Đặt phòng trực tuyến, thanh toán VietQR.', `content` = '<h2 class=\"page-heading bottom-indent\">Giới thiệu Thaithinh Hotel</h2>\n<div>\n<p>Thaithinh Hotel là hệ thống khách sạn 3 cơ sở tại Hồ Chí Minh, Đà Nẵng và Hà Nội, tổng cộng 50 phòng. Mỗi cơ sở đặt ở khu trung tâm của thành phố để quý khách thuận tiện di chuyển, dù đi công tác hay nghỉ dưỡng.</p>\n\n<h3>Hệ thống cơ sở</h3>\n<ul>\n<li><strong>Cơ sở 1 – Trung tâm</strong> · 123 Lê Lợi, Quận 1, Hồ Chí Minh · 20 phòng · ĐT: 028 3822 0001</li>\n<li><strong>Cơ sở 2 – Bờ biển</strong> · 456 Võ Nguyên Giáp, Sơn Trà, Đà Nẵng · 15 phòng · ĐT: 0236 3822 0002</li>\n<li><strong>Cơ sở 3 – Phố cổ</strong> · 789 Hàng Trống, Hoàn Kiếm, Hà Nội · 15 phòng · ĐT: 024 3822 0003</li>\n</ul>\n\n<h3>Dịch vụ có tại mọi cơ sở</h3>\n<ul>\n<li>Wifi miễn phí toàn khách sạn</li>\n<li>Lễ tân trực 24/7</li>\n<li>Dọn phòng hàng ngày</li>\n</ul>\n\n<h3>Đặt phòng và thanh toán</h3>\n<p>Quý khách đặt phòng trực tiếp trên website, không qua trung gian. Sau khi chọn phòng, hệ thống sinh mã VietQR để chuyển khoản; giao dịch được đối soát tự động theo mã đơn nên phòng được giữ ngay khi thanh toán thành công.</p>\n<p>Giờ nhận phòng từ <strong>14:00</strong>, trả phòng trước <strong>12:00</strong>.</p>\n\n<h3>Liên hệ</h3>\n<p>Email: <a href=\"mailto:support@hotel.local\">support@hotel.local</a> · Hotline: 0987654321</p>\n</div>\n' WHERE `id_cms` = 4 AND `id_lang` = 1;
UPDATE `qlo_cms_lang` SET `meta_title` = 'Giới thiệu', `meta_description` = 'Thaithinh Hotel - hệ thống 3 cơ sở tại Hồ Chí Minh, Đà Nẵng, Hà Nội với 50 phòng. Đặt phòng trực tuyến, thanh toán VietQR.', `content` = '<h2 class=\"page-heading bottom-indent\">Giới thiệu Thaithinh Hotel</h2>\n<div>\n<p>Thaithinh Hotel là hệ thống khách sạn 3 cơ sở tại Hồ Chí Minh, Đà Nẵng và Hà Nội, tổng cộng 50 phòng. Mỗi cơ sở đặt ở khu trung tâm của thành phố để quý khách thuận tiện di chuyển, dù đi công tác hay nghỉ dưỡng.</p>\n\n<h3>Hệ thống cơ sở</h3>\n<ul>\n<li><strong>Cơ sở 1 – Trung tâm</strong> · 123 Lê Lợi, Quận 1, Hồ Chí Minh · 20 phòng · ĐT: 028 3822 0001</li>\n<li><strong>Cơ sở 2 – Bờ biển</strong> · 456 Võ Nguyên Giáp, Sơn Trà, Đà Nẵng · 15 phòng · ĐT: 0236 3822 0002</li>\n<li><strong>Cơ sở 3 – Phố cổ</strong> · 789 Hàng Trống, Hoàn Kiếm, Hà Nội · 15 phòng · ĐT: 024 3822 0003</li>\n</ul>\n\n<h3>Dịch vụ có tại mọi cơ sở</h3>\n<ul>\n<li>Wifi miễn phí toàn khách sạn</li>\n<li>Lễ tân trực 24/7</li>\n<li>Dọn phòng hàng ngày</li>\n</ul>\n\n<h3>Đặt phòng và thanh toán</h3>\n<p>Quý khách đặt phòng trực tiếp trên website, không qua trung gian. Sau khi chọn phòng, hệ thống sinh mã VietQR để chuyển khoản; giao dịch được đối soát tự động theo mã đơn nên phòng được giữ ngay khi thanh toán thành công.</p>\n<p>Giờ nhận phòng từ <strong>14:00</strong>, trả phòng trước <strong>12:00</strong>.</p>\n\n<h3>Liên hệ</h3>\n<p>Email: <a href=\"mailto:support@hotel.local\">support@hotel.local</a> · Hotline: 0987654321</p>\n</div>\n' WHERE `id_cms` = 4 AND `id_lang` = 2;
UPDATE `qlo_cms_lang` SET `meta_title` = 'Thanh toán an toàn', `meta_description` = 'Thaithinh Hotel nhận thanh toán qua mã VietQR, đối soát tự động theo mã đơn. Website không lưu thông tin thẻ hay tài khoản ngân hàng.', `content` = '<h2 class=\"page-heading bottom-indent\">Thanh toán an toàn</h2>\n<div>\n<p>Thaithinh Hotel nhận thanh toán bằng <strong>chuyển khoản ngân hàng qua mã VietQR</strong>. Đây là phương thức thanh toán duy nhất trên website.</p>\n\n<h3>Quy trình</h3>\n<ol>\n<li>Quý khách chọn cơ sở, ngày ở và loại phòng, sau đó xác nhận đặt phòng.</li>\n<li>Hệ thống sinh một mã VietQR riêng cho đơn của quý khách, đã điền sẵn số tiền và nội dung chuyển khoản theo mã đơn.</li>\n<li>Quý khách quét mã bằng ứng dụng ngân hàng và chuyển khoản.</li>\n<li>Hệ thống đối soát tự động theo mã đơn. Khi số tiền khớp, đơn chuyển sang trạng thái đã thanh toán và email xác nhận được gửi tới quý khách.</li>\n</ol>\n\n<h3>Vì sao an toàn</h3>\n<ul>\n<li>Giao dịch diễn ra trong ứng dụng ngân hàng của chính quý khách. Website không yêu cầu và <strong>không lưu bất kỳ thông tin thẻ hay tài khoản ngân hàng</strong> nào.</li>\n<li>Nội dung chuyển khoản gắn với mã đơn cụ thể, nên tiền vào đúng đơn, tránh nhầm lẫn.</li>\n<li>Số tiền đã điền sẵn trong mã QR, quý khách không phải gõ tay.</li>\n</ul>\n\n<h3>Lưu ý</h3>\n<p>Vui lòng <strong>giữ nguyên nội dung chuyển khoản</strong> mà hệ thống tạo ra. Nếu sửa nội dung, giao dịch có thể không được đối soát tự động và phòng chưa được giữ.</p>\n<p>Nếu đã chuyển khoản nhưng sau 15 phút đơn chưa đổi trạng thái, xin liên hệ <a href=\"mailto:support@hotel.local\">support@hotel.local</a> hoặc hotline 0987654321 kèm mã đơn để được kiểm tra.</p>\n</div>\n' WHERE `id_cms` = 5 AND `id_lang` = 1;
UPDATE `qlo_cms_lang` SET `meta_title` = 'Thanh toán an toàn', `meta_description` = 'Thaithinh Hotel nhận thanh toán qua mã VietQR, đối soát tự động theo mã đơn. Website không lưu thông tin thẻ hay tài khoản ngân hàng.', `content` = '<h2 class=\"page-heading bottom-indent\">Thanh toán an toàn</h2>\n<div>\n<p>Thaithinh Hotel nhận thanh toán bằng <strong>chuyển khoản ngân hàng qua mã VietQR</strong>. Đây là phương thức thanh toán duy nhất trên website.</p>\n\n<h3>Quy trình</h3>\n<ol>\n<li>Quý khách chọn cơ sở, ngày ở và loại phòng, sau đó xác nhận đặt phòng.</li>\n<li>Hệ thống sinh một mã VietQR riêng cho đơn của quý khách, đã điền sẵn số tiền và nội dung chuyển khoản theo mã đơn.</li>\n<li>Quý khách quét mã bằng ứng dụng ngân hàng và chuyển khoản.</li>\n<li>Hệ thống đối soát tự động theo mã đơn. Khi số tiền khớp, đơn chuyển sang trạng thái đã thanh toán và email xác nhận được gửi tới quý khách.</li>\n</ol>\n\n<h3>Vì sao an toàn</h3>\n<ul>\n<li>Giao dịch diễn ra trong ứng dụng ngân hàng của chính quý khách. Website không yêu cầu và <strong>không lưu bất kỳ thông tin thẻ hay tài khoản ngân hàng</strong> nào.</li>\n<li>Nội dung chuyển khoản gắn với mã đơn cụ thể, nên tiền vào đúng đơn, tránh nhầm lẫn.</li>\n<li>Số tiền đã điền sẵn trong mã QR, quý khách không phải gõ tay.</li>\n</ul>\n\n<h3>Lưu ý</h3>\n<p>Vui lòng <strong>giữ nguyên nội dung chuyển khoản</strong> mà hệ thống tạo ra. Nếu sửa nội dung, giao dịch có thể không được đối soát tự động và phòng chưa được giữ.</p>\n<p>Nếu đã chuyển khoản nhưng sau 15 phút đơn chưa đổi trạng thái, xin liên hệ <a href=\"mailto:support@hotel.local\">support@hotel.local</a> hoặc hotline 0987654321 kèm mã đơn để được kiểm tra.</p>\n</div>\n' WHERE `id_cms` = 5 AND `id_lang` = 2;

